//! Arrow boundary helpers shared across the SAML scalar/table functions.
//!
//! The worker is a thin adapter: it reads a `BLOB`/`VARCHAR` input cell into
//! bytes, hands them to the pure `saml-core` engine, and marshals the engine's
//! typed output back into Arrow `STRUCT` / `LIST` / `TIMESTAMPTZ` columns. The
//! `STRUCT` field sets are defined once here so `on_bind` and `process` agree
//! exactly (a mismatch makes DuckDB reject the batch).

use std::sync::Arc;

use arrow_array::cast::AsArray;
use arrow_array::{Array, ArrayRef, TimestampMicrosecondArray};

use arrow_schema::{DataType, Field, TimeUnit};
use vgi_rpc::{Result, RpcError};

/// The `TIMESTAMPTZ` Arrow type the worker emits (microseconds, UTC).
pub fn ts_type() -> DataType {
    DataType::Timestamp(TimeUnit::Microsecond, Some("UTC".into()))
}

/// Build a UTC `TIMESTAMPTZ` array from epoch-microsecond options.
pub fn ts_array(vals: Vec<Option<i64>>) -> ArrayRef {
    Arc::new(TimestampMicrosecondArray::from(vals).with_timezone("UTC"))
}

/// `LIST(VARCHAR)` element type — the element field is `item`/nullable and MUST
/// match between the declared schema and the built array.
pub fn list_varchar_type() -> DataType {
    DataType::List(Arc::new(Field::new("item", DataType::Utf8, true)))
}

/// Read a `BLOB` (`Binary`/`LargeBinary`) or `VARCHAR` (`Utf8`/`LargeUtf8`)
/// input cell at `row` as raw bytes, or `None` if the cell is null. Errors only
/// on a genuinely wrong column type.
pub fn input_bytes(col: &ArrayRef, row: usize) -> Result<Option<Vec<u8>>> {
    if col.is_null(row) {
        return Ok(None);
    }
    Ok(Some(match col.data_type() {
        DataType::Binary => col.as_binary::<i32>().value(row).to_vec(),
        DataType::LargeBinary => col.as_binary::<i64>().value(row).to_vec(),
        DataType::Utf8 => col.as_string::<i32>().value(row).as_bytes().to_vec(),
        DataType::LargeUtf8 => col.as_string::<i64>().value(row).as_bytes().to_vec(),
        other => {
            return Err(RpcError::value_error(format!(
                "expected a BLOB or VARCHAR SAML message, got {other:?}"
            )))
        }
    }))
}

#[cfg(test)]
pub mod test_support {
    use super::*;
    use arrow_array::builder::BinaryBuilder;
    use arrow_array::RecordBatch;
    use arrow_schema::{Schema, SchemaRef};
    use vgi::arguments::Arguments;
    use vgi::{BindParams, ProcessParams, ScalarFunction};
    use vgi_rpc::Result;

    /// A single-column `BLOB` input batch from raw message bytes (`None` = NULL).
    pub fn blob_batch(rows: &[Option<&[u8]>]) -> RecordBatch {
        let mut b = BinaryBuilder::new();
        for r in rows {
            match r {
                Some(s) => b.append_value(s),
                None => b.append_null(),
            }
        }
        let arr: ArrayRef = Arc::new(b.finish());
        let schema = Arc::new(Schema::new(vec![Field::new(
            "msg",
            arr.data_type().clone(),
            true,
        )]));
        RecordBatch::try_new(schema, vec![arr]).unwrap()
    }

    pub fn process_params(output_schema: SchemaRef, arguments: Arguments) -> ProcessParams {
        ProcessParams {
            substream_id: None,
            if_none_match: None,
            if_modified_since: None,
            bind_output_schema: output_schema.clone(),
            current_pushdown_filters: None,
            output_schema,
            input_schema: None,
            execution_id: Vec::new(),
            bind_opaque_data: Vec::new(),
            init_opaque_data: Vec::new(),
            arguments,
            settings: Default::default(),
            secrets: Default::default(),
            auth_principal: None,
            projection_ids: None,
            pushdown_filters: None,
            join_keys: Vec::new(),
            storage: None,
            order_by_column: None,
            order_by_direction: None,
            order_by_null_order: None,
            order_by_limit: None,
            tablesample_percentage: None,
            tablesample_seed: None,
            attach_opaque_data: None,
            transaction_opaque_data: None,
            at_unit: None,
            at_value: None,
            copy_from: None,
            split_payloads: None,
        }
    }

    /// Run a scalar over a one-column BLOB batch, returning the result column.
    pub fn run_scalar_blob<F: ScalarFunction>(f: &F, rows: &[Option<&[u8]>]) -> Result<ArrayRef> {
        let batch = blob_batch(rows);
        let bind = BindParams {
            input_schema: Some(batch.schema()),
            ..Default::default()
        };
        let bound = f.on_bind(&bind)?;
        let params = process_params(bound.output_schema.clone(), Arguments::default());
        Ok(f.process(&params, &batch)?.column(0).clone())
    }

    /// The declared output `DataType` from `on_bind`.
    pub fn bound_type<F: ScalarFunction>(f: &F) -> DataType {
        let bound = f.on_bind(&BindParams::default()).unwrap();
        bound.output_schema.field(0).data_type().clone()
    }
}

//! Composed example queries: realistic SQL that combines two or more of the
//! worker's own functions in one query (a fan-out joined to another fan-out, a
//! triage gate in front of the decoders, a per-message security verdict).
//!
//! Each query is defined exactly once here and referenced from both the
//! schema-level `vgi.example_queries` list (`lib.rs`) and the example list of
//! the function that drives it (that function's first five examples are what
//! the vgi-lint agent simulator shows). Every query is self-contained (literal
//! SAML), offline, and deterministic.

use vgi::FunctionExample;

/// Build a [`FunctionExample`] from a `(description, sql)` pair.
pub fn example((description, sql): (&str, &str)) -> FunctionExample {
    FunctionExample {
        sql: sql.into(),
        description: description.into(),
        expected_output: None,
    }
}

/// XSW coverage check — `assertions` LEFT JOIN `signatures` on the signed
/// Reference ID. Driven by `assertions`.
pub const UNSIGNED_ASSERTIONS: (&str, &str) = (
    "XSW coverage check: list every assertion in a Response next to the signature (if any) whose Reference points at it; the wrapped evil assertion _evil shows no covering signature.",
    "WITH m AS (SELECT '<samlp:Response xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\" ID=\"_r\"><saml:Assertion ID=\"_evil\"><saml:Issuer>https://idp.example.com</saml:Issuer><saml:Subject><saml:NameID>admin@example.com</saml:NameID></saml:Subject></saml:Assertion><saml:Assertion ID=\"_a1\"><saml:Issuer>https://idp.example.com</saml:Issuer><ds:Signature><ds:SignedInfo><ds:Reference URI=\"#_a1\"/></ds:SignedInfo></ds:Signature><saml:Subject><saml:NameID>alice@example.com</saml:NameID></saml:Subject></saml:Assertion></samlp:Response>' AS msg), asr AS (SELECT a.* FROM m, UNNEST(saml.main.assertions(m.msg)) AS _(a)), sig AS (SELECT s.* FROM m, UNNEST(saml.main.signatures(m.msg)) AS _(s)) SELECT asr.idx, asr.id, asr.subject, sig.idx AS covering_signature FROM asr LEFT JOIN sig ON sig.references_id = asr.id ORDER BY asr.idx",
);

/// Triage gate in front of the decoders — `well_formed` decides, then
/// `message_type` + `decode` read only the usable blobs. Driven by `well_formed`.
pub const TRIAGE_THEN_DECODE: (&str, &str) = (
    "Triage a batch of blobs before decoding: well_formed classifies each one, and only the usable messages are passed on to message_type and decode for their issuer.",
    "SELECT t.blob_id, (saml.main.well_formed(t.blob)).kind AS triage, CASE WHEN (saml.main.well_formed(t.blob)).ok THEN saml.main.message_type(t.blob) END AS msg_type, CASE WHEN (saml.main.well_formed(t.blob)).ok THEN (saml.main.decode(t.blob)).issuer END AS issuer FROM (VALUES (1, '<saml:Assertion xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"_a\"><saml:Issuer>https://idp.example.com</saml:Issuer></saml:Assertion>'), (2, 'not a saml message'), (3, '<!DOCTYPE x [<!ENTITY e SYSTEM \"file:///etc/passwd\">]><samlp:Response xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\"/>')) AS t(blob_id, blob) ORDER BY t.blob_id",
);

/// Per-login security verdict — `decode` (who/what), `signature` (signed?) and
/// `anomalies` (structural flags) in one row per message. Driven by `anomalies`.
pub const LOGIN_VERDICT: (&str, &str) = (
    "Per-login security verdict: who each message claims to be (decode), whether it carries a signature (signature), and which structural flags fire (anomalies); login-1 is signed but its digest does not match (digest-mismatch), login-2 is unsigned and carries two assertions (multiple-assertions).",
    "WITH logins AS (SELECT * FROM (VALUES ('login-1', '<saml:Assertion xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\" ID=\"_a\"><saml:Issuer>https://idp.example.com</saml:Issuer><ds:Signature><ds:SignedInfo><ds:Reference URI=\"#_a\"/></ds:SignedInfo></ds:Signature><saml:Subject><saml:NameID>alice@example.com</saml:NameID></saml:Subject></saml:Assertion>'), ('login-2', '<samlp:Response xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"_r\"><saml:Assertion ID=\"_a1\"><saml:Issuer>https://idp.example.com</saml:Issuer><saml:Subject><saml:NameID>bob@example.com</saml:NameID></saml:Subject></saml:Assertion><saml:Assertion ID=\"_a2\"><saml:Issuer>https://idp.example.com</saml:Issuer><saml:Subject><saml:NameID>admin@example.com</saml:NameID></saml:Subject></saml:Assertion></samlp:Response>')) AS v(login_id, msg)) SELECT login_id, (saml.main.decode(msg)).subject AS subject, (saml.main.signature(msg)).signed AS signed, saml.main.anomalies(msg) AS flags FROM logins ORDER BY login_id",
);

/// Who holds which role — `decode` for the subject + `attributes` fanned out
/// and re-aggregated per subject. Driven by `attributes`.
pub const SUBJECT_ROLES: (&str, &str) = (
    "Roll a multi-valued role attribute up per subject: decode supplies the NameID and the attributes fan-out supplies each role value.",
    "WITH m AS (SELECT '<saml:Assertion xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"_a\"><saml:Subject><saml:NameID>alice@example.com</saml:NameID></saml:Subject><saml:AttributeStatement><saml:Attribute Name=\"role\"><saml:AttributeValue>admin</saml:AttributeValue><saml:AttributeValue>user</saml:AttributeValue></saml:Attribute><saml:Attribute Name=\"dept\"><saml:AttributeValue>finance</saml:AttributeValue></saml:Attribute></saml:AttributeStatement></saml:Assertion>' AS msg) SELECT (saml.main.decode(m.msg)).subject AS subject, list_sort(list(a.value)) AS roles FROM m, UNNEST(saml.main.attributes(m.msg)) AS _(a) WHERE a.name = 'role' GROUP BY ALL ORDER BY subject",
);

/// Every composed example, in schema-level order.
pub const ALL: [(&str, &str); 4] = [
    UNSIGNED_ASSERTIONS,
    TRIAGE_THEN_DECODE,
    LOGIN_VERDICT,
    SUBJECT_ROLES,
];

//! Native `saml` VGI worker binary.
//!
//! A standalone executable DuckDB launches and talks to over Apache Arrow IPC
//! (`ATTACH 'vgi-saml' AS saml (TYPE vgi, LOCATION '…')`). All function
//! registration lives in the library crate so the wasm build serves an
//! identical worker.

fn main() {
    // Logs MUST go to stderr — stdout is the Arrow-IPC channel.
    let _ = env_logger::Builder::from_env(env_logger::Env::default().filter_or("VGI_LOG", "info"))
        .format_timestamp_millis()
        .try_init();

    saml_worker::build_worker().run();
}

//! Shared helpers for the per-object discovery/description metadata that the
//! `vgi-lint` strict profile expects on **every** function and table.
//!
//! Each function/table surfaces these in its `FunctionMetadata.tags`:
//! - `vgi.title` (VGI124)        — human-friendly display name
//! - `vgi.doc_llm` (VGI112) — concise prose aimed at LLMs
//! - `vgi.doc_md` (VGI113)  — short Markdown description
//! - `vgi.keywords` (VGI126/VGI138) — a JSON array of search terms/synonyms
//!
//! Per-object `vgi.source_url` is intentionally NOT emitted here: `vgi.source_url`
//! belongs on the catalog object only (VGI139). The catalog's `source_url` field
//! already points at the repo.

/// Encode comma-separated keywords as the JSON array of strings that
/// `vgi.keywords` requires (VGI138). Each term is trimmed and empty terms are
/// dropped; the result is e.g. `["units","convert","length"]`.
pub fn keywords_json(keywords: &str) -> String {
    let items: Vec<String> = keywords
        .split(',')
        .map(str::trim)
        .filter(|k| !k.is_empty())
        // JSON-escape each keyword (covers quotes/backslashes) by emitting a
        // one-element array and stripping the surrounding brackets.
        .map(|k| {
            let escaped = k.replace('\\', "\\\\").replace('"', "\\\"");
            format!("\"{escaped}\"")
        })
        .collect();
    format!("[{}]", items.join(","))
}

/// JSON-encode a string into `out`, wrapping it in double quotes and escaping
/// the characters JSON requires.
fn json_string(out: &mut String, s: &str) {
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Serialize a function's usage examples into the `vgi.example_queries` tag shape
/// (VGI515): a JSON list of `{"description": ..., "sql": ...}` objects.
///
/// Every function ALSO carries the same examples in [`vgi::FunctionMetadata::examples`]
/// (the native `duckdb_functions().examples` column), but that column is a bare
/// `VARCHAR[]` of SQL strings and drops the per-example description. The linter
/// merges the two carriers by SQL, so emitting the identical `sql` here lets the
/// described tag entry win — giving every example a human-readable description
/// without duplicating the query text.
pub fn example_queries_json(examples: &[vgi::FunctionExample]) -> String {
    let mut out = String::from("[");
    for (i, ex) in examples.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str("{\"description\":");
        json_string(&mut out, &ex.description);
        out.push_str(",\"sql\":");
        json_string(&mut out, &ex.sql);
        out.push('}');
    }
    out.push(']');
    out
}

/// Build the `vgi.agent_test_tasks` JSON value: a fixed suite of analyst tasks
/// that `vgi-lint simulate` runs. Each `(name, prompt)` pair becomes a task
/// object shown to the simulated analyst. The graders (`reference_sql`, the
/// canonical solution) are private and live in the `vgi-agent-tests.yaml`
/// sidecar at the repo root, keyed by task name (VGI416).
pub fn agent_test_tasks_json(tasks: &[(&str, &str)]) -> String {
    fn esc(s: &str) -> String {
        s.replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('\n', "\\n")
    }
    let items: Vec<String> = tasks
        .iter()
        .map(|(name, prompt)| {
            format!(
                "{{\"name\":\"{}\",\"prompt\":\"{}\"}}",
                esc(name),
                esc(prompt)
            )
        })
        .collect();
    format!("[{}]", items.join(","))
}

/// Build the standard per-object discovery/description tags (title, LLM/MD docs,
/// keywords, and the `vgi.category` naming an entry in the schema's registry).
///
/// `relative_path` is the implementing file relative to `units-worker/src`; it is
/// retained for call-site documentation but no longer emitted as a per-object
/// `vgi.source_url` (that tag is catalog-only — VGI139).
pub fn object_tags(
    title: &str,
    description_llm: &str,
    description_md: &str,
    keywords: &str,
    category: &str,
    _relative_path: &str,
) -> Vec<(String, String)> {
    vec![
        ("vgi.title".to_string(), title.to_string()),
        ("vgi.doc_llm".to_string(), description_llm.to_string()),
        ("vgi.doc_md".to_string(), description_md.to_string()),
        ("vgi.keywords".to_string(), keywords_json(keywords)),
        // VGI408/409: name one of the schema's `vgi.categories` registry entries.
        ("vgi.category".to_string(), category.to_string()),
    ]
}

//! `saml.anomalies(msg) -> LIST<VARCHAR>` — the XSW / Golden-SAML / structural
//! flag set. Empty list = no structural red flag found (NOT a safety guarantee;
//! Golden SAML leaves none — that verdict is a downstream trust-table JOIN).

use std::sync::Arc;

use arrow_array::builder::{ListBuilder, StringBuilder};
use arrow_array::{ArrayRef, RecordBatch};
use arrow_schema::{DataType, Field};
use vgi::{
    ArgSpec, BindParams, BindResponse, FunctionExample, FunctionMetadata, ProcessParams,
    ScalarFunction,
};
use vgi_rpc::{Result, RpcError};

use crate::arrow_io::{input_bytes, list_varchar_type};

pub struct Anomalies;

impl ScalarFunction for Anomalies {
    fn name(&self) -> &str {
        "anomalies"
    }

    fn metadata(&self) -> FunctionMetadata {
        let examples = vec![
            FunctionExample {
                sql: "SELECT saml.main.anomalies('<samlp:Response \
                  xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" \
                  xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\">\
                  <saml:Assertion ID=\"_a1\"/><saml:Assertion ID=\"_a2\"/></samlp:Response>');"
                    .into(),
                description: "Surface signature-wrapping / structural red flags (here, \
                          multiple-assertions) for a message."
                    .into(),
                expected_output: None,
            },
            crate::composed::example(crate::composed::LOGIN_VERDICT),
        ];
        let mut tags = crate::meta::object_tags(
            "SAML Signature-Wrapping Anomalies",
            "Return the structural anomaly flags for a SAML message as a `LIST(VARCHAR)`. These \
             are the invariants every XML Signature Wrapping (XSW1-XSW8) attack violates plus \
             the XXE-class text-extraction tells: multiple-assertions, \
             signature-covers-other-element, reference-uri-id-mismatch, \
             unsigned-assertion-in-signed-response, signature-placement-anomaly, \
             detached-signature, nameid-comment-splitting, digest-mismatch, \
             c14n-inclusive-on-moved-assertion, and encrypted-assertion-present. An EMPTY list \
             is not a safety guarantee — Golden SAML (a forgery with a stolen but valid IdP \
             key) leaves no structural trace, so combine this with a trust-table JOIN on \
             signer_cert_sha256.",
            "List XSW / structural red flags for a SAML message (e.g. `multiple-assertions`, \
             `signature-covers-other-element`, `digest-mismatch`); empty != safe.",
            "xsw, signature wrapping, golden saml, anomalies, multiple assertions, \
             digest mismatch, detached signature, comment splitting, attack detection, \
             detection engineering",
            "Detect",
            "scalar/anomalies.rs",
        );
        tags.push((
            "vgi.example_queries".into(),
            crate::meta::example_queries_json(&examples),
        ));
        FunctionMetadata {
            description:
                "Flag XSW (XML Signature Wrapping) / Golden-SAML / structural anomalies as \
                          a LIST<VARCHAR>; empty list = no structural red flag found (not a safety \
                          guarantee)"
                    .into(),
            return_type: Some(list_varchar_type()),
            examples,
            tags,
            ..Default::default()
        }
    }

    fn argument_specs(&self) -> Vec<ArgSpec> {
        vec![ArgSpec::any_column(
            "msg",
            0,
            "A SAML 2.0 message to scan for signature-wrapping and structural attack indicators. \
             Pass the value straight from your column — the worker content-sniffs and normalizes \
             the transport wrapper automatically, whether the message arrived as raw XML or an \
             encoded SAMLResponse blob.",
        )]
    }

    fn on_bind(&self, _params: &BindParams) -> Result<BindResponse> {
        Ok(BindResponse::result(list_varchar_type()))
    }

    fn process(&self, params: &ProcessParams, batch: &RecordBatch) -> Result<RecordBatch> {
        let col = batch.column(0);
        let field = Arc::new(Field::new("item", DataType::Utf8, true));
        let mut b = ListBuilder::new(StringBuilder::new()).with_field(field);
        for i in 0..batch.num_rows() {
            match input_bytes(col, i)? {
                Some(bytes) => {
                    for flag in saml_core::api::anomalies(&bytes) {
                        b.values().append_value(flag);
                    }
                    b.append(true); // non-null (possibly empty) list
                }
                None => b.append(false), // NULL input → NULL list
            }
        }
        let arr: ArrayRef = Arc::new(b.finish());
        RecordBatch::try_new(params.output_schema.clone(), vec![arr])
            .map_err(|e| RpcError::runtime_error(e.to_string()))
    }
}

//! `saml.authn(msg) -> STRUCT(...)` — the `AuthnStatement` + `AuthnContext`.

use std::sync::Arc;

use arrow_array::builder::StringBuilder;
use arrow_array::{ArrayRef, RecordBatch, StructArray};
use arrow_buffer::NullBuffer;
use arrow_schema::{DataType, Field, Fields};
use vgi::{
    ArgSpec, BindParams, BindResponse, FunctionExample, FunctionMetadata, ProcessParams,
    ScalarFunction,
};
use vgi_rpc::{Result, RpcError};

use crate::arrow_io::{input_bytes, ts_array, ts_type};

pub fn fields() -> Fields {
    Fields::from(vec![
        Field::new("authn_instant", ts_type(), true),
        Field::new("session_index", DataType::Utf8, true),
        Field::new("session_not_on_or_after", ts_type(), true),
        Field::new("class_ref", DataType::Utf8, true),
        Field::new("decl_ref", DataType::Utf8, true),
        Field::new("authenticating_authority", DataType::Utf8, true),
    ])
}

pub struct AuthnFn;

impl ScalarFunction for AuthnFn {
    fn name(&self) -> &str {
        "authn"
    }

    fn metadata(&self) -> FunctionMetadata {
        let examples = vec![FunctionExample {
            sql: "SELECT (saml.main.authn('<saml:Assertion \
                  xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\"><saml:AuthnStatement>\
                  <saml:AuthnContext><saml:AuthnContextClassRef>\
                  urn:oasis:names:tc:SAML:2.0:ac:classes:PasswordProtectedTransport\
                  </saml:AuthnContextClassRef></saml:AuthnContext></saml:AuthnStatement>\
                  </saml:Assertion>')).class_ref;"
                .into(),
            description: "Read the AuthnContext class (e.g. detect MFA downgrade).".into(),
            expected_output: None,
        }];
        let mut tags = crate::meta::object_tags(
            "SAML AuthnContext",
            "Extract a SAML assertion's AuthnStatement and AuthnContext as a struct: the \
             AuthnInstant and SessionNotOnOrAfter (`TIMESTAMPTZ`, UTC), the SessionIndex, the \
             AuthnContextClassRef / DeclRef (the authentication method, e.g. \
             PasswordProtectedTransport vs an MFA class — useful for spotting downgrades), and \
             any AuthenticatingAuthority. Returns NULL when there is no AuthnStatement.",
            "Get the AuthnStatement/AuthnContext (instant, session, auth class) as a struct.",
            "authn, authncontext, authnstatement, session index, authninstant, class ref, \
             authentication method, mfa downgrade, sso session",
            "Decode",
            "scalar/authn.rs",
        );
        tags.push((
            "vgi.example_queries".into(),
            crate::meta::example_queries_json(&examples),
        ));
        FunctionMetadata {
            description: "Extract the AuthnStatement + AuthnContext: STRUCT(authn_instant \
                          TIMESTAMPTZ, session_index VARCHAR, session_not_on_or_after TIMESTAMPTZ, \
                          class_ref VARCHAR, decl_ref VARCHAR, authenticating_authority VARCHAR)"
                .into(),
            examples,
            tags,
            return_type: Some(DataType::Struct(fields())),
            ..Default::default()
        }
    }

    fn argument_specs(&self) -> Vec<ArgSpec> {
        vec![ArgSpec::any_column(
            "msg",
            0,
            "A SAML 2.0 message whose AuthnStatement to extract. The worker content-sniffs and \
             normalizes the transport wrapper automatically, whether the message arrived as raw \
             XML or an encoded SAMLResponse blob, so pass the value straight from your column.",
        )]
    }

    fn on_bind(&self, _params: &BindParams) -> Result<BindResponse> {
        Ok(BindResponse::result(DataType::Struct(fields())))
    }

    fn process(&self, params: &ProcessParams, batch: &RecordBatch) -> Result<RecordBatch> {
        let col = batch.column(0);
        let rows = batch.num_rows();
        let mut instant = Vec::with_capacity(rows);
        let mut session_index = StringBuilder::new();
        let mut session_noa = Vec::with_capacity(rows);
        let mut class_ref = StringBuilder::new();
        let mut decl_ref = StringBuilder::new();
        let mut authority = StringBuilder::new();
        let mut valid = Vec::with_capacity(rows);

        let opt_str = |b: &mut StringBuilder, v: &Option<String>| match v {
            Some(s) => b.append_value(s),
            None => b.append_null(),
        };

        for i in 0..rows {
            let parsed = match input_bytes(col, i)? {
                Some(bytes) => saml_core::api::authn(&bytes),
                None => None,
            };
            match parsed {
                Some(a) => {
                    instant.push(a.authn_instant);
                    opt_str(&mut session_index, &a.session_index);
                    session_noa.push(a.session_not_on_or_after);
                    opt_str(&mut class_ref, &a.class_ref);
                    opt_str(&mut decl_ref, &a.decl_ref);
                    opt_str(&mut authority, &a.authenticating_authority);
                    valid.push(true);
                }
                None => {
                    instant.push(None);
                    session_index.append_null();
                    session_noa.push(None);
                    class_ref.append_null();
                    decl_ref.append_null();
                    authority.append_null();
                    valid.push(false);
                }
            }
        }

        let arrays: Vec<ArrayRef> = vec![
            ts_array(instant),
            Arc::new(session_index.finish()),
            ts_array(session_noa),
            Arc::new(class_ref.finish()),
            Arc::new(decl_ref.finish()),
            Arc::new(authority.finish()),
        ];
        let out: ArrayRef = Arc::new(StructArray::new(
            fields(),
            arrays,
            Some(NullBuffer::from(valid)),
        ));
        RecordBatch::try_new(params.output_schema.clone(), vec![out])
            .map_err(|e| RpcError::runtime_error(e.to_string()))
    }
}

//! `saml.conditions(msg) -> STRUCT(...)` — the validity window + audience/usage
//! constraints. The worker does NOT decide "expired" (clock-skew policy is the
//! caller's — compare to `now()` in SQL).

use std::sync::Arc;

use arrow_array::builder::{BooleanBuilder, ListBuilder, StringBuilder, UInt32Builder};
use arrow_array::{ArrayRef, RecordBatch, StructArray};
use arrow_buffer::NullBuffer;
use arrow_schema::{DataType, Field, Fields};
use vgi::{
    ArgSpec, BindParams, BindResponse, FunctionExample, FunctionMetadata, ProcessParams,
    ScalarFunction,
};
use vgi_rpc::{Result, RpcError};

use crate::arrow_io::{input_bytes, list_varchar_type, ts_array, ts_type};

pub fn fields() -> Fields {
    Fields::from(vec![
        Field::new("not_before", ts_type(), true),
        Field::new("not_on_or_after", ts_type(), true),
        Field::new("audiences", list_varchar_type(), true),
        Field::new("one_time_use", DataType::Boolean, true),
        Field::new("proxy_restriction_count", DataType::UInt32, true),
        Field::new("proxy_audiences", list_varchar_type(), true),
    ])
}

fn list_builder() -> ListBuilder<StringBuilder> {
    ListBuilder::new(StringBuilder::new()).with_field(Arc::new(Field::new(
        "item",
        DataType::Utf8,
        true,
    )))
}

pub struct Conditions;

impl ScalarFunction for Conditions {
    fn name(&self) -> &str {
        "conditions"
    }

    fn metadata(&self) -> FunctionMetadata {
        let examples = vec![FunctionExample {
            sql: "SELECT (saml.main.conditions('<saml:Assertion \
                  xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\">\
                  <saml:Conditions NotBefore=\"2026-01-01T00:00:00Z\" \
                  NotOnOrAfter=\"2026-01-01T01:00:00Z\"/></saml:Assertion>')).not_on_or_after;"
                .into(),
            description: "Read the assertion validity window for an own-skew expiry check.".into(),
            expected_output: None,
        }];
        let mut tags = crate::meta::object_tags(
            "SAML Conditions Window",
            "Extract a SAML assertion's Conditions as a struct: the NotBefore / NotOnOrAfter \
             validity window (`TIMESTAMPTZ`, UTC), the AudienceRestriction audiences, the \
             OneTimeUse flag, and any ProxyRestriction count and audiences. The worker \
             surfaces the window but never decides 'expired' — clock-skew tolerance is the \
             caller's policy, so compare against now() in SQL.",
            "Get the assertion validity window + audiences as a struct; you decide expiry \
             against `now()`.",
            "conditions, validity window, notbefore, notonorafter, audience, audiencerestriction, \
             onetimeuse, proxyrestriction, expiry, timestamptz",
            "Decode",
            "scalar/conditions.rs",
        );
        tags.push((
            "vgi.example_queries".into(),
            crate::meta::example_queries_json(&examples),
        ));
        FunctionMetadata {
            description: "Extract the assertion Conditions: STRUCT(not_before TIMESTAMPTZ, \
                          not_on_or_after TIMESTAMPTZ, audiences LIST<VARCHAR>, one_time_use BOOL, \
                          proxy_restriction_count UINTEGER, proxy_audiences LIST<VARCHAR>). No \
                          'expired' verdict — compare to now() yourself."
                .into(),
            examples,
            tags,
            return_type: Some(DataType::Struct(fields())),
            ..Default::default()
        }
    }

    fn argument_specs(&self) -> Vec<ArgSpec> {
        vec![ArgSpec::any_column(
            "msg",
            0,
            "A SAML 2.0 message whose assertion Conditions validity window to extract. The worker \
             content-sniffs and normalizes the transport wrapper automatically, whether the \
             message arrived as raw XML or an encoded SAMLResponse blob, so pass the value \
             straight from your column.",
        )]
    }

    fn on_bind(&self, _params: &BindParams) -> Result<BindResponse> {
        Ok(BindResponse::result(DataType::Struct(fields())))
    }

    fn process(&self, params: &ProcessParams, batch: &RecordBatch) -> Result<RecordBatch> {
        let col = batch.column(0);
        let rows = batch.num_rows();
        let mut not_before = Vec::with_capacity(rows);
        let mut not_after = Vec::with_capacity(rows);
        let mut audiences = list_builder();
        let mut one_time = BooleanBuilder::new();
        let mut proxy_count = UInt32Builder::new();
        let mut proxy_aud = list_builder();
        let mut valid = Vec::with_capacity(rows);

        for i in 0..rows {
            let parsed = match input_bytes(col, i)? {
                Some(bytes) => saml_core::api::conditions(&bytes),
                None => None,
            };
            match parsed {
                Some(c) => {
                    not_before.push(c.not_before);
                    not_after.push(c.not_on_or_after);
                    for a in &c.audiences {
                        audiences.values().append_value(a);
                    }
                    audiences.append(true);
                    one_time.append_value(c.one_time_use);
                    proxy_count.append_value(c.proxy_restriction_count);
                    for a in &c.proxy_audiences {
                        proxy_aud.values().append_value(a);
                    }
                    proxy_aud.append(true);
                    valid.push(true);
                }
                None => {
                    not_before.push(None);
                    not_after.push(None);
                    audiences.append(false);
                    one_time.append_null();
                    proxy_count.append_null();
                    proxy_aud.append(false);
                    valid.push(false);
                }
            }
        }

        let arrays: Vec<ArrayRef> = vec![
            ts_array(not_before),
            ts_array(not_after),
            Arc::new(audiences.finish()),
            Arc::new(one_time.finish()),
            Arc::new(proxy_count.finish()),
            Arc::new(proxy_aud.finish()),
        ];
        let out: ArrayRef = Arc::new(StructArray::new(
            fields(),
            arrays,
            Some(NullBuffer::from(valid)),
        ));
        RecordBatch::try_new(params.output_schema.clone(), vec![out])
            .map_err(|e| RpcError::runtime_error(e.to_string()))
    }
}

//! `saml.decode(msg) -> STRUCT(...)` — the §A field map. Accepts raw XML,
//! base64, base64+DEFLATE, or URL-encoded; content-sniffs and normalizes. Never
//! errors on malformed input — returns a struct with null fields and
//! `signed=false` (use `well_formed` for the reason).

use std::sync::Arc;

use arrow_array::builder::{BooleanBuilder, ListBuilder, StringBuilder, UInt32Builder};
use arrow_array::{ArrayRef, RecordBatch, StructArray};
use arrow_buffer::NullBuffer;
use arrow_schema::{DataType, Field, Fields};
use vgi::{
    ArgSpec, BindParams, BindResponse, FunctionExample, FunctionMetadata, ProcessParams,
    ScalarFunction,
};
use vgi_rpc::{Result, RpcError};

use crate::arrow_io::{input_bytes, list_varchar_type, ts_array, ts_type};

pub fn fields() -> Fields {
    let s = |n: &str| Field::new(n, DataType::Utf8, true);
    let t = |n: &str| Field::new(n, ts_type(), true);
    Fields::from(vec![
        s("message_type"),
        s("response_id"),
        s("assertion_id"),
        s("issuer"),
        s("subject"),
        s("subject_format"),
        s("subject_sp_qualifier"),
        s("confirmation_method"),
        s("recipient"),
        s("in_response_to"),
        t("subject_not_on_or_after"),
        t("not_before"),
        t("not_on_or_after"),
        s("audience"),
        Field::new("audiences", list_varchar_type(), true),
        t("authn_instant"),
        s("session_index"),
        s("authn_context"),
        s("status"),
        s("destination"),
        t("issue_instant"),
        s("version"),
        Field::new("assertion_count", DataType::UInt32, true),
        Field::new("encrypted_count", DataType::UInt32, true),
        Field::new("signed", DataType::Boolean, true),
    ])
}

pub struct Decode;

impl ScalarFunction for Decode {
    fn name(&self) -> &str {
        "decode"
    }

    fn metadata(&self) -> FunctionMetadata {
        let examples = vec![FunctionExample {
            sql: "SELECT (saml.main.decode('<saml:Assertion \
                  xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"_a\">\
                  <saml:Issuer>https://idp.example.com</saml:Issuer><saml:Subject>\
                  <saml:NameID>alice@example.com</saml:NameID></saml:Subject>\
                  </saml:Assertion>')).subject;"
                .into(),
            description: "Decode a SAML assertion to its subject + core fields.".into(),
            expected_output: None,
        }];
        let mut tags = crate::meta::object_tags(
            "Decode SAML Message",
            "Decode a SAML 2.0 Response or Assertion to a struct of its core fields — \
             response_id / assertion_id, issuer, subject (+ NameID format and SP qualifier), \
             SubjectConfirmation recipient / in_response_to, the Conditions NotBefore / \
             NotOnOrAfter window, audience(s), AuthnInstant / SessionIndex / AuthnContext class, \
             Status, Destination, IssueInstant, Version, the assertion/encrypted counts, and \
             whether a top-level Signature is present. The input is content-sniffed: it accepts \
             raw XML, base64 (HTTP-POST binding), base64+raw-DEFLATE (HTTP-Redirect binding), \
             or a URL-encoded wrapper. It never errors on malformed input — a bad blob yields a \
             struct with null fields and signed=false (call well_formed for the reason). \
             Timestamps are `TIMESTAMPTZ` (UTC); the worker surfaces the window but does not \
             decide 'expired'.",
            "Decode a SAML Response/Assertion to a struct of subject, issuer, audience, the \
             validity window, authn context, status, ids and counts; null fields on bad input.",
            "decode saml, samlresponse, assertion, subject, issuer, audience, nameid, \
             conditions, authn context, status, base64, deflate, redirect binding, post binding",
            "Decode",
            "scalar/decode.rs",
        );
        tags.push((
            "vgi.example_queries".into(),
            crate::meta::example_queries_json(&examples),
        ));
        FunctionMetadata {
            description: "Decode a SAML message (raw XML / base64 / base64+DEFLATE / URL-encoded) \
                          to a STRUCT of core fields: subject, issuer, audience, conditions window, \
                          authn_context, status, ids, counts, and signed. Never errors on bad \
                          input — returns null fields + signed=false (see well_formed)."
                .into(),
            examples,
            tags,
            return_type: Some(DataType::Struct(fields())),
            ..Default::default()
        }
    }

    fn argument_specs(&self) -> Vec<ArgSpec> {
        vec![ArgSpec::any_column(
            "msg",
            0,
            "The SAML message to decode: raw XML, base64, base64+DEFLATE (HTTP-Redirect), or a \
             URL-encoded wrapper. Content-sniffed automatically; malformed input yields null \
             fields, not an error.",
        )]
    }

    fn on_bind(&self, _params: &BindParams) -> Result<BindResponse> {
        Ok(BindResponse::result(DataType::Struct(fields())))
    }

    fn process(&self, params: &ProcessParams, batch: &RecordBatch) -> Result<RecordBatch> {
        let col = batch.column(0);
        let rows = batch.num_rows();

        // String columns (in field order, minus timestamps/list/counts/signed).
        let mut message_type = StringBuilder::new();
        let mut response_id = StringBuilder::new();
        let mut assertion_id = StringBuilder::new();
        let mut issuer = StringBuilder::new();
        let mut subject = StringBuilder::new();
        let mut subject_format = StringBuilder::new();
        let mut subject_sp_qualifier = StringBuilder::new();
        let mut confirmation_method = StringBuilder::new();
        let mut recipient = StringBuilder::new();
        let mut in_response_to = StringBuilder::new();
        let mut audience = StringBuilder::new();
        let mut session_index = StringBuilder::new();
        let mut authn_context = StringBuilder::new();
        let mut status = StringBuilder::new();
        let mut destination = StringBuilder::new();
        let mut version = StringBuilder::new();
        let mut subject_noa = Vec::with_capacity(rows);
        let mut not_before = Vec::with_capacity(rows);
        let mut not_after = Vec::with_capacity(rows);
        let mut authn_instant = Vec::with_capacity(rows);
        let mut issue_instant = Vec::with_capacity(rows);
        let mut audiences = ListBuilder::new(StringBuilder::new())
            .with_field(Arc::new(Field::new("item", DataType::Utf8, true)));
        let mut assertion_count = UInt32Builder::new();
        let mut encrypted_count = UInt32Builder::new();
        let mut signed = BooleanBuilder::new();
        let mut valid = Vec::with_capacity(rows);

        let opt = |b: &mut StringBuilder, v: &Option<String>| match v {
            Some(s) => b.append_value(s),
            None => b.append_null(),
        };

        for i in 0..rows {
            let Some(bytes) = input_bytes(col, i)? else {
                // NULL input → null struct row; still feed every child once.
                message_type.append_null();
                response_id.append_null();
                assertion_id.append_null();
                issuer.append_null();
                subject.append_null();
                subject_format.append_null();
                subject_sp_qualifier.append_null();
                confirmation_method.append_null();
                recipient.append_null();
                in_response_to.append_null();
                audience.append_null();
                session_index.append_null();
                authn_context.append_null();
                status.append_null();
                destination.append_null();
                version.append_null();
                subject_noa.push(None);
                not_before.push(None);
                not_after.push(None);
                authn_instant.push(None);
                issue_instant.push(None);
                audiences.append(false);
                assertion_count.append_null();
                encrypted_count.append_null();
                signed.append_null();
                valid.push(false);
                continue;
            };

            // Non-null input always yields a non-null struct (fields may be null).
            let d = saml_core::api::decode(&bytes);
            opt(&mut message_type, &d.message_type);
            opt(&mut response_id, &d.response_id);
            opt(&mut assertion_id, &d.assertion_id);
            opt(&mut issuer, &d.issuer);
            opt(&mut subject, &d.subject);
            opt(&mut subject_format, &d.subject_format);
            opt(&mut subject_sp_qualifier, &d.subject_sp_qualifier);
            opt(&mut confirmation_method, &d.confirmation_method);
            opt(&mut recipient, &d.recipient);
            opt(&mut in_response_to, &d.in_response_to);
            opt(&mut audience, &d.audience);
            opt(&mut session_index, &d.session_index);
            opt(&mut authn_context, &d.authn_context);
            opt(&mut status, &d.status);
            opt(&mut destination, &d.destination);
            opt(&mut version, &d.version);
            subject_noa.push(d.subject_not_on_or_after);
            not_before.push(d.not_before);
            not_after.push(d.not_on_or_after);
            authn_instant.push(d.authn_instant);
            issue_instant.push(d.issue_instant);
            for a in &d.audiences {
                audiences.values().append_value(a);
            }
            audiences.append(true);
            assertion_count.append_value(d.assertion_count);
            encrypted_count.append_value(d.encrypted_count);
            signed.append_value(d.signed);
            valid.push(true);
        }

        let arrays: Vec<ArrayRef> = vec![
            Arc::new(message_type.finish()),
            Arc::new(response_id.finish()),
            Arc::new(assertion_id.finish()),
            Arc::new(issuer.finish()),
            Arc::new(subject.finish()),
            Arc::new(subject_format.finish()),
            Arc::new(subject_sp_qualifier.finish()),
            Arc::new(confirmation_method.finish()),
            Arc::new(recipient.finish()),
            Arc::new(in_response_to.finish()),
            ts_array(subject_noa),
            ts_array(not_before),
            ts_array(not_after),
            Arc::new(audience.finish()),
            Arc::new(audiences.finish()),
            ts_array(authn_instant),
            Arc::new(session_index.finish()),
            Arc::new(authn_context.finish()),
            Arc::new(status.finish()),
            Arc::new(destination.finish()),
            ts_array(issue_instant),
            Arc::new(version.finish()),
            Arc::new(assertion_count.finish()),
            Arc::new(encrypted_count.finish()),
            Arc::new(signed.finish()),
        ];
        let out: ArrayRef = Arc::new(StructArray::new(
            fields(),
            arrays,
            Some(NullBuffer::from(valid)),
        ));
        RecordBatch::try_new(params.output_schema.clone(), vec![out])
            .map_err(|e| RpcError::runtime_error(e.to_string()))
    }
}

//! The fan-out functions — `attributes`, `signatures`, `assertions` — as scalar
//! functions returning `LIST<STRUCT>`.
//!
//! ## Why scalar `LIST<STRUCT>` and not a table function
//!
//! These naturally fan one message into ≥0 rows, which the spec sketches as a
//! LATERAL table function (`FROM raw_saml r, LATERAL saml.attributes(r.msg) a`).
//! But DuckDB's table-function binder only accepts **literal constant**
//! arguments — a correlated column (`r.msg`) is rejected with "the function only
//! supports literals as parameters". So per-row fan-out **over a column** —
//! which is the entire point of bulk forensic SQL over millions of messages —
//! cannot be a table function. We deliver it as a scalar returning a
//! `LIST<STRUCT>` and the caller `UNNEST`s it, which *does* accept a correlated
//! column and yields the identical long-form result:
//!
//! ```sql
//! SELECT r.login_id, a.name, a.value
//! FROM raw_saml r, UNNEST(saml.main.attributes(r.saml_response)) AS _(a)
//! WHERE a.name = 'role';
//! ```

use std::sync::Arc;

use arrow_array::builder::{
    BooleanBuilder, ListBuilder, StringBuilder, StructBuilder, UInt32Builder,
};
use arrow_array::{ArrayRef, RecordBatch};
use arrow_schema::{DataType, Field, Fields};
use vgi::{
    ArgSpec, BindParams, BindResponse, FunctionExample, FunctionMetadata, ProcessParams,
    ScalarFunction,
};
use vgi_rpc::{Result, RpcError};

use crate::arrow_io::input_bytes;

fn list_of(fields: Fields) -> DataType {
    DataType::List(Arc::new(Field::new("item", DataType::Struct(fields), true)))
}

fn list_builder(fields: Fields) -> ListBuilder<StructBuilder> {
    let sb = StructBuilder::from_fields(fields.clone(), 0);
    ListBuilder::new(sb).with_field(Arc::new(Field::new("item", DataType::Struct(fields), true)))
}

fn opt_str(b: &mut StructBuilder, idx: usize, v: &Option<String>) {
    let sb = b.field_builder::<StringBuilder>(idx).unwrap();
    match v {
        Some(s) => sb.append_value(s),
        None => sb.append_null(),
    }
}
fn put_str(b: &mut StructBuilder, idx: usize, v: &str) {
    b.field_builder::<StringBuilder>(idx)
        .unwrap()
        .append_value(v);
}
fn put_u32(b: &mut StructBuilder, idx: usize, v: u32) {
    b.field_builder::<UInt32Builder>(idx)
        .unwrap()
        .append_value(v);
}
fn put_bool(b: &mut StructBuilder, idx: usize, v: bool) {
    b.field_builder::<BooleanBuilder>(idx)
        .unwrap()
        .append_value(v);
}

fn msg_arg() -> Vec<ArgSpec> {
    vec![ArgSpec::any_column(
        "msg",
        0,
        "A SAML 2.0 message to fan out into rows with UNNEST(...) over a column. The worker \
         content-sniffs and normalizes the transport wrapper automatically, whether the message \
         arrived as raw XML or an encoded SAMLResponse blob, so pass the value straight from your \
         column.",
    )]
}

/// The worker's guaranteed-runnable, verified example set (VGI509). Each entry
/// carries an `expected_result` so `vgi-lint --execute` checks it against a live
/// worker; every query is self-contained (a literal SAML message), catalog-
/// qualified, and covers a representative slice of the surface. Carried on the
/// `attributes` object — VGI509 only requires it on one object.
const EXECUTABLE_EXAMPLES: &str = r#"[
  {
    "description": "Identify a SAML message by its root element.",
    "sql": "SELECT saml.main.message_type('<samlp:Response xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\"/>') AS kind",
    "expected_result": [{"kind": "Response"}]
  },
  {
    "description": "Triage why a blob is not a usable SAML message.",
    "sql": "SELECT (saml.main.well_formed('not a saml message')).kind AS kind",
    "expected_result": [{"kind": "bad-base64"}]
  },
  {
    "description": "Base64-decode a SAMLResponse POST field to its XML text.",
    "sql": "SELECT saml.main.b64decode('PHNhbWw+')::VARCHAR AS decoded",
    "expected_result": [{"decoded": "<saml>"}]
  },
  {
    "description": "Flag the multiple-assertions XSW indicator on a two-assertion Response.",
    "sql": "SELECT list_contains(saml.main.anomalies('<samlp:Response xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"_r\"><saml:Assertion ID=\"_a1\"/><saml:Assertion ID=\"_a2\"/></samlp:Response>'), 'multiple-assertions') AS has_multi",
    "expected_result": [{"has_multi": true}]
  },
  {
    "description": "Explode a multi-valued attribute into one row per value.",
    "sql": "SELECT a.value AS value FROM UNNEST(saml.main.attributes('<saml:Assertion xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\"><saml:AttributeStatement><saml:Attribute Name=\"role\"><saml:AttributeValue>admin</saml:AttributeValue><saml:AttributeValue>user</saml:AttributeValue></saml:Attribute></saml:AttributeStatement></saml:Assertion>')) AS _(a) ORDER BY a.value",
    "expected_result": [{"value": "admin"}, {"value": "user"}]
  }
]"#;

// ------------------------------- attributes --------------------------------

pub fn attribute_fields() -> Fields {
    Fields::from(vec![
        Field::new("statement_idx", DataType::UInt32, true),
        Field::new("name", DataType::Utf8, true),
        Field::new("name_format", DataType::Utf8, true),
        Field::new("friendly_name", DataType::Utf8, true),
        Field::new("value", DataType::Utf8, true),
        Field::new("value_type", DataType::Utf8, true),
    ])
}

pub struct Attributes;

impl ScalarFunction for Attributes {
    fn name(&self) -> &str {
        "attributes"
    }
    fn metadata(&self) -> FunctionMetadata {
        let examples = vec![
            FunctionExample {
                sql: "SELECT a.name, a.value FROM UNNEST(saml.main.attributes('<saml:Assertion \
                  xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\"><saml:AttributeStatement>\
                  <saml:Attribute Name=\"role\"><saml:AttributeValue>admin\
                  </saml:AttributeValue><saml:AttributeValue>user</saml:AttributeValue>\
                  </saml:Attribute></saml:AttributeStatement></saml:Assertion>')) AS _(a) \
                  ORDER BY a.value;"
                    .into(),
                description: "Explode a multi-valued attribute to long form (one row per value)."
                    .into(),
                expected_output: None,
            },
            crate::composed::example(crate::composed::SUBJECT_ROLES),
        ];
        let mut tags = crate::meta::object_tags(
            "Explode SAML Attributes",
            "Return a SAML assertion's AttributeStatement(s) as a \
             `LIST(STRUCT(statement_idx, name, name_format, friendly_name, value, value_type))`, \
             one struct per AttributeValue. UNNEST it over a column to explode attributes to long \
             form, so multi-valued attributes (roles, groups) fan out into one row each and can \
